INSERT INTO dynasties (id, name, start_year, end_year) VALUES ('jin', '金朝', 1115, 1234)
INSERT INTO events (dynasty_id, year, year_end, lng, lat, short, title, detail, impact, place, category) VALUES
  ('jin', 1114, 1115, 131.25, 45.55, '宁江州之战', '宁江州之战 · 女真抗辽首捷', '完颜阿骨打率女真军在宁江州击败辽军，随后乘胜攻取宾州，辽东诸部相继响应。', '女真军由部落联盟转为能够持续作战的政治军事力量，为金朝建国及随后灭辽奠定基础。', '宁江州（今吉林扶余一带）', 'military'),
  ('jin', 1115, 1115, 126.57, 45.55, '金朝建立', '完颜阿骨打称帝 · 金朝建立', '完颜阿骨打于会宁府称帝，国号金，改元收国，建立女真族政权。', '东北亚政治格局从辽宋对峙转为辽金宋三方竞争，会宁府成为金朝早期政治中心。', '会宁府（今哈尔滨阿城）', 'era'),
  ('jin', 1116, 1117, 126.57, 45.55, '金取辽东', '金军攻取辽东诸州', '金军连续攻取辽阳府及辽东诸州，辽在东北的行政与军事控制迅速瓦解。', '金朝获得稳定的农业、人口与交通资源，国家形态和财政基础明显增强。', '辽阳府', 'military'),
  ('jin', 1119, 1120, 126.57, 45.55, '收国改元', '金太祖改元天辅', '金太祖在统一女真诸部并扩张辽东后改元天辅，整顿猛安谋克与地方治理。', '猛安谋克制度逐渐成为金朝军政组织骨架，也塑造了金朝独特的族群统治结构。', '会宁府', 'era'),
  ('jin', 1120, 1125, 118.78, 32.06, '海上之盟', '宋金海上之盟', '北宋遣使渡海与金约定夹攻辽朝，宋取燕云，金取辽上京、中京等地，双方约定灭辽后以岁币代替原输辽岁币。', '宋朝失去辽作为北方缓冲，金则获得直接南下的战略通道，联盟最终反而加速北宋覆亡。', '登州与金使往来路线', 'era'),
  ('jin', 1122, 1123, 116.4, 39.9, '金克燕京', '金军攻克燕京', '金军在辽南京燕京击败辽军，燕京一度由宋接收，后因宋军无力守备而重新归金。', '金朝取得华北门户和南下跳板，宋金边界与外交矛盾由此迅速激化。', '燕京（今北京）', 'military'),
  ('jin', 1125, 1125, 121.6, 43.5, '辽朝灭亡', '金灭辽 · 天祚帝被俘', '金军追击辽天祚帝，天祚帝被俘，辽朝正式灭亡，金成为北方最强政权。', '辽亡改变宋辽百余年均势，金军随即转向南下攻宋，靖康之变进入直接倒计时。', '应州及夹山一带', 'military'),
  ('jin', 1125, 1126, 114.35, 34.78, '第一次攻宋', '金军第一次南下攻宋', '金军以宋收纳张觉等人为由分东西两路南下，围攻太原并进逼汴京，宋廷以议和暂时解围。', '北宋边防和动员体系暴露严重缺陷，金朝确认宋军难以抵挡，为再次南侵积累信心。', '太原·汴京', 'military'),
  ('jin', 1126, 1127, 114.35, 34.78, '靖康之变', '金军攻陷汴京 · 北宋灭亡', '金军再次南下攻破汴京，俘宋徽宗、宋钦宗及宗室百官，北宋灭亡。', '金朝控制华北并建立伪楚等傀儡政权，宋室南渡，南北对峙成为此后东亚政治主线。', '东京开封府', 'military'),
  ('jin', 1127, 1130, 112.55, 37.87, '刘豫立齐', '金立刘豫为齐帝', '金朝扶植刘豫在大名、东平等地建立伪齐政权，以其作为统治华北和进攻南宋的缓冲。', '金对华北由直接军事占领转向羁縻与代理统治，但伪齐的征敛和战争也加剧当地社会动荡。', '大名府', 'era'),
  ('jin', 1128, 1129, 118.78, 32.06, '金军渡淮', '金军南侵与宋金对峙形成', '金军突破淮河防线，宋高宗南渡后以江淮、襄汉等地组织防御，双方逐步形成长期战争边界。', '金军未能迅速灭宋，南宋获得重建军政体系的时间，金宋战争转入反复拉锯。', '淮河流域', 'military'),
  ('jin', 1130, 1130, 120.16, 30.25, '兀术北撤', '韩世忠黄天荡阻击金军', '金兀术南下后自建康撤退，韩世忠水军在黄天荡设伏阻击，金军历时多日方得脱围。', '金军深入江南的攻势受挫，宋军江南水网防御价值凸显，金朝转而重视淮北与中原战场。', '黄天荡（今南京东南）', 'military'),
  ('jin', 1134, 1137, 114.31, 30.52, '伪齐攻宋', '伪齐与金联军南侵', '刘豫在金支持下进攻南宋，宋军在襄阳、郢州等地反击，伪齐军政体系逐渐失去作用。', '金发现代理统治难以压服南宋，废除伪齐并准备直接统治华北，宋金战争格局再次调整。', '襄阳·郢州', 'military'),
  ('jin', 1137, 1138, 114.35, 34.78, '废刘豫', '金废伪齐并直辖河南', '金熙宗废黜刘豫，撤销伪齐，将河南、陕西等地纳入金朝直接统治。', '金朝完成从征服到行政接管的关键转变，华北官制、赋税和军户体系开始全面金化。', '汴京及河南府', 'era'),
  ('jin', 1141, 1142, 118.78, 32.06, '绍兴和议', '宋金绍兴和议', '宋高宗与金议和，以淮水中流、大散关为界，宋向金称臣并输送岁币，双方暂时停战。', '宋金南北分治格局正式固定，金朝获得相对稳定的南部边界与财政收益，和平延续数十年。', '临安·淮水—大散关', 'military'),
  ('jin', 1153, 1153, 116.4, 39.9, '海陵迁都', '海陵王迁都燕京', '金海陵王完颜亮将都城由上京会宁府迁至燕京，改名中都，并营建宫城与官署。', '政治中心南移便于控制华北、对抗南宋，也加速金朝制度与城市文化的中原化。', '中都（今北京）', 'era'),
  ('jin', 1161, 1162, 118.78, 32.06, '采石之战', '采石之战 · 金军南侵失败', '海陵王大举南侵，金军在采石、瓜洲等处渡江失败，南宋军民击退金军，海陵王随后在军中被杀。', '金朝统一南方的企图破灭，宋金边界恢复，金内部政变促成世宗即位和政治转向。', '采石矶（今马鞍山）', 'military'),
  ('jin', 1161, 1189, 112.55, 37.87, '大定之治', '金世宗大定之治', '金世宗即位后整饬吏治、减轻赋役，调和女真与汉地关系，恢复战争破坏的北方经济。', '金朝国力在大定年间达到鼎盛，人口、农业和财政恢复，为随后数十年对宋和平提供基础。', '中都·上京', 'economy'),
  ('jin', 1173, 1190, 116.4, 39.9, '女真文字教育', '金朝推行女真文字与学校', '金朝在官府和女真聚居区推行女真文字教育，编纂字书并以学校培养女真官员。', '女真文字和教育制度强化了族群认同，同时推动金朝吸收中原文书行政与科举传统。', '中都', 'invention'),
  ('jin', 1206, 1210, 118.78, 32.06, '宋金再战', '宋金嘉定战争', '南宋在韩侂胄主持下发动北伐，金军反攻并攻取襄阳等地，双方最终议和。', '南宋北伐失败，金朝取得外交优势，但战争消耗也削弱其应对蒙古崛起的能力。', '襄阳·淮西', 'military'),
  ('jin', 1211, 1215, 116.4, 39.9, '蒙古南侵', '蒙古攻金与中都陷落', '成吉思汗率蒙古军攻金，金宣宗迁都南京开封，中都在蒙古围攻后陷落。', '金朝北方防线崩溃并失去燕云核心，政权被迫南迁，蒙古成为决定金朝命运的新强权。', '中都（今北京）', 'military'),
  ('jin', 1217, 1224, 114.35, 34.78, '金迁汴守局', '金朝迁都南京开封', '金宣宗为避蒙古压力迁都南京开封，集中兵力经营黄河以南，并与南宋长期交战。', '迁都暂时保全金朝中原腹地，却加剧河南、陕西的军费与徭役负担，南北双方民生俱受影响。', '南京开封府', 'era'),
  ('jin', 1232, 1233, 114.35, 34.78, '三峰山之战', '三峰山之战 · 金军主力覆灭', '蒙古军在三峰山击溃金军主力，金朝再无力在河南组织大规模野战，开封陷入孤城困境。', '金朝军事体系遭到决定性打击，蒙古与南宋夹攻金朝的最后阶段由此展开。', '三峰山（今禹州西南）', 'military'),
  ('jin', 1234, 1234, 114.9, 33.0, '蔡州城破', '蔡州之战 · 金朝灭亡', '宋蒙联军攻破蔡州，金哀宗自缢，末帝完颜承麟战死，金朝灭亡。', '金亡后南宋与蒙古直接接壤，原有缓冲消失；宋蒙战争随即爆发，东亚格局进入蒙古帝国主导的新阶段。', '蔡州（今河南汝南）', 'military')
